-- ============================================================
-- V29: Create ods.cif_accno (account -> CIF mapping) and seed
--      data from acct_cif_demo.csv.
-- Rows with an empty account number are loaded with acct_no = NULL.
-- ============================================================

CREATE TABLE IF NOT EXISTS ods.cif_accno (
    cif      varchar(20) NOT NULL,
    acct_no  varchar(20)
);

CREATE INDEX IF NOT EXISTS idx_cif_accno_cif     ON ods.cif_accno (cif);
CREATE INDEX IF NOT EXISTS idx_cif_accno_acct_no ON ods.cif_accno (acct_no);

